			if len(c.ext) != len(c.want) {
				t.Fatalf("extension has %d entries, want %d", len(c.ext), len(c.want))
			}
			for i, e := range c.want {
				if c.ext[i] != e {
					t.Errorf("entry %d = %+v, want %+v", i, c.ext[i], e)
				}
			}
